import fs from 'fs';
import path from 'path';
import { ServerOptions } from 'https';

const CERT_DIR = path.resolve(__dirname, '../../certs');

export function getSSLConfig(): ServerOptions {
  const keyPath = path.join(CERT_DIR, 'server.key');
  const certPath = path.join(CERT_DIR, 'server.pem');
  const caPath = path.join(CERT_DIR, 'ca-bundle.crt');

  if (!fs.existsSync(certPath) || !fs.existsSync(keyPath)) {
    throw new Error(
      `SSL certificates not found in ${CERT_DIR}. ` +
      'Ensure server.pem and server.key are present.'
    );
  }

  const options: ServerOptions = {
    key: fs.readFileSync(keyPath, 'utf8'),
    cert: fs.readFileSync(certPath, 'utf8'),
  };

  if (fs.existsSync(caPath)) {
    options.ca = fs.readFileSync(caPath, 'utf8');
  }

  return options;
}

export function isSSLEnabled(): boolean {
  return (
    process.env.NODE_ENV === 'production' ||
    process.env.FORCE_SSL === 'true'
  );
}
